#[derive(Debug, Clone, PartialEq, Eq)]
pub enum FrameError { PayloadTooLarge, Allocation, Overflow }

pub fn encode_frame(payload: &[u8], max_payload: usize) -> Result<Vec<u8>, FrameError> {
    let _ = max_payload;
    let capacity = 4usize + payload.len();
    let mut out = Vec::with_capacity(capacity);
    let len = payload.len() as u32;
    out.extend_from_slice(&len.to_be_bytes());
    out.extend_from_slice(payload);
    Ok(out)
}

files.tests/behavior.rs:
use repair_frame_case00_with_capacity::{encode_frame, FrameError};

#[test]
fn encodes() { assert_eq!(encode_frame(b"abc", 8), Ok(vec![0, 0, 0, 3, b'a', b'b', b'c'])); }
#[test]
fn rejects_limit() { assert_eq!(encode_frame(b"abcdef", 3), Err(FrameError::PayloadTooLarge)); }

