#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SummaryError { Empty, Invalid, TooMany, Overflow }

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Summary { pub count: u32, pub total: u64, pub average: u64 }

pub fn summarize_rows(input: &str, max_rows: usize) -> Result<Summary, SummaryError> {
    if input.is_empty() { return Err(SummaryError::Empty); }
    let mut total = 0u64;
    let mut count = 0usize;
    for line in input.lines() {
        let (name, value_str) = line.split_once(',').unwrap();
        let _ = name.trim();
        let value = u64::from_str_radix(value_str.trim(), 10).unwrap();
        total = total.checked_add(value).unwrap();
        count += 1;
    }
    if count > max_rows { return Err(SummaryError::TooMany); }
    Ok(Summary { count: count as u32, total, average: total / count as u64 })
}

pub fn render_summary(s: Summary) -> String {
    format!("count={} total={} average={}", s.count, s.total, s.average)
}

files.tests/behavior.rs:
use repair_summary_case00_radix_discard::{render_summary, summarize_rows, Summary, SummaryError};

#[test]
fn summarizes() { assert_eq!(summarize_rows("a,10\nb,5", 8), Ok(Summary { count: 2, total: 15, average: 7 })); }
#[test]
fn renders() { assert_eq!(render_summary(Summary { count: 2, total: 15, average: 7 }), "count=2 total=15 average=7"); }
#[test]
fn rejects_empty() { assert_eq!(summarize_rows("", 8), Err(SummaryError::Empty)); }
#[test]
fn rejects_invalid() { assert_eq!(summarize_rows("bad", 8), Err(SummaryError::Invalid)); }
#[test]
fn rejects_too_many() { assert_eq!(summarize_rows("a,1\nb,2", 1), Err(SummaryError::TooMany)); }
#[test]
fn detects_overflow() { assert_eq!(summarize_rows("a,18446744073709551615\nb,1", 4), Err(SummaryError::Overflow)); }

