        let _ = name.trim();
        let value = u64::from_str_radix(value_str.trim(), 10).unwrap();
        total = total.checked_add(value).unwrap();
        count += 1;
    }
    if count > max_rows { return Err(SummaryError::TooMany); }
    Ok(Summary { count: count as u32, total, average: total / count as u64 })
}

